INSERT  IGNORE INTO `products` (`product_id`, `name`, `brand`, `category_id`, `price`, `currency`, `margin_rate`, `recommendation_score`, `description`, `specs`, `source_updated_at`, `created_at`, `updated_at`) VALUES ('P001','Aero 無線藍牙耳機','Pulso','3c-accessories',1890.00,'TWD',0.4200,82,'輕巧入耳式設計，通勤、運動都適用。支援快充，充電 10 分鐘可聽 1 小時。','{\"續航\": \"單次 6 小時，含充電盒 24 小時\", \"連線\": \"藍牙 5.3\", \"重量\": \"單耳 4.8g\", \"防水等級\": \"IPX4\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P002','Aero 無線藍牙耳機','Pulso','3c-accessories',1790.00,'TWD',0.4000,64,'輕巧入耳式設計，適合通勤使用。','{\"續航\": \"單次 6 小時，含充電盒 24 小時\", \"連線\": \"藍牙 5.3\", \"防水等級\": \"IPX4\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P003','輕量行動電源 10000mAh','Voltri','3c-accessories',690.00,'TWD',0.2800,76,'比一張信用卡大一點，放口袋剛好。支援 20W 快充，可同時充兩台裝置。','{\"容量\": \"10000mAh\", \"輸出\": \"USB-C 20W／USB-A 18W\", \"重量\": \"185g\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P004','65W 氮化鎵快充頭','Voltri','3c-accessories',890.00,'TWD',0.3300,79,'一個充電頭搞定筆電、平板與手機，體積只有傳統充電器的一半。','{\"孔位\": \"USB-C x2、USB-A x1\", \"輸出\": \"最高 65W\", \"重量\": \"112g\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P005','Studio 降噪頭戴式耳機','Pulso','3c-accessories',4290.00,'TWD',0.5500,88,'主動降噪搭配耳罩式設計，長時間配戴也舒適。可折疊收納。','{\"續航\": \"開啟降噪 30 小時\", \"連線\": \"藍牙 5.3、3.5mm 有線\", \"重量\": \"250g\", \"降噪\": \"主動降噪（ANC）\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P006','磁吸手機支架','Voltri','3c-accessories',390.00,'TWD',0.6200,70,'強力磁吸，單手就能把手機吸上、取下。可調整角度，適合車用與桌面。','{\"材質\": \"鋁合金\", \"相容性\": \"支援 MagSafe 手機，或搭配引磁片使用\", \"可調角度\": \"360 度\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P007','K87 機械式鍵盤','Keyfold','3c-accessories',2690.00,'TWD',0.3100,74,'87 鍵精簡配置，軸體可熱插拔，支援藍牙、2.4G 與有線三種連線。','{\"背光\": \"白光\", \"軸體\": \"茶軸（可熱插拔）\", \"連線\": \"藍牙／2.4G／USB-C 有線\", \"配置\": \"87 鍵\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P008','USB-C 編織充電線 1.5m','Voltri','3c-accessories',290.00,'TWD',0.5800,66,'尼龍編織線材，耐彎折。支援 60W 快充與資料傳輸。','{\"功率\": \"最高 60W\", \"接頭\": \"USB-C 對 USB-C\", \"長度\": \"1.5m\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P009','真空保溫瓶 500ml','青嶼 Qingyu','home-living',780.00,'TWD',0.4500,80,'雙層真空不鏽鋼，保溫 12 小時、保冷 24 小時。瓶口加寬，方便放冰塊與清洗。','{\"保溫\": \"12 小時\", \"容量\": \"500ml\", \"材質\": \"316 不鏽鋼\", \"重量\": \"290g\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P010','陶瓷手沖濾杯組','棲木 Qimu','home-living',0.00,'TWD',0.3800,72,'手工陶瓷濾杯搭配同色系分享壺，適合 1–2 人份手沖。附 40 張濾紙。','{\"材質\": \"陶瓷、耐熱玻璃\", \"內容物\": \"濾杯、分享壺（400ml）、濾紙 40 張\", \"適用人數\": \"1–2 人\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P011','手工大豆蠟燭（雪松）','微光 Glimmer','home-living',650.00,'TWD',0.6400,68,'天然大豆蠟手工製作，雪松與佛手柑香調，燃燒時間約 40 小時。','{\"重量\": \"200g\", \"香調\": \"雪松、佛手柑\", \"燃燒時間\": \"約 40 小時\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P012','亞麻抱枕套 45x45','棲木 Qimu','home-living',480.00,'TWD',0.5200,61,'水洗亞麻材質，越洗越柔軟。隱形拉鍊設計，不含枕心。','{\"尺寸\": \"45 x 45 cm\", \"材質\": \"100% 亞麻\", \"內容物\": \"枕套 1 入（不含枕心）\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P013','不鏽鋼雙層便當盒','青嶼 Qingyu','home-living',920.00,'TWD',0.3000,73,'雙層不鏽鋼便當盒，附防漏矽膠蓋與餐具。可直接放入電鍋蒸煮。','{\"容量\": \"上層 450ml、下層 600ml\", \"材質\": \"304 不鏽鋼\", \"可用電鍋加熱\": \"可（矽膠蓋需取下）\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P014','超細纖維浴巾','Halden','home-living',560.00,'TWD',0.4100,65,'超細纖維材質，吸水力是一般棉質浴巾的 3 倍，快乾不易有異味。','{\"尺寸\": \"70 x 140 cm\", \"材質\": \"超細纖維\", \"重量\": \"380g\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P015','擴香石禮盒','微光 Glimmer','home-living',1280.00,'TWD',0.6000,77,'石膏擴香石搭配兩瓶精油，送禮自用兩相宜。附手寫卡片。','{\"內容物\": \"擴香石 x1、精油 10ml x2、手寫卡 x1\", \"精油香調\": \"白茶、薰衣草\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P016','摺疊收納箱（2 入）','Halden','home-living',699.00,'TWD',0.2700,58,'不用時可摺平收納，附蓋可堆疊。適合衣櫃與床下收納。','{\"尺寸\": \"40 x 30 x 25 cm\", \"數量\": \"2 入\", \"材質\": \"PP 塑膠\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P017','TPE 瑜珈墊 6mm','Nordvik','sports-outdoor',990.00,'TWD',0.3600,75,'雙面防滑 TPE 材質，6mm 厚度保護膝蓋與手腕。附收納背帶。','{\"厚度\": \"6mm\", \"尺寸\": \"183 x 61 cm\", \"材質\": \"TPE\", \"重量\": \"900g\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P018','輕量跑步腰包','Nordvik','sports-outdoor',450.00,'TWD',0.4800,69,'彈性布料貼合腰部，跑步不晃動。可放 6.7 吋手機與鑰匙。','{\"容量\": \"可放 6.7 吋手機\", \"材質\": \"萊卡彈性布\", \"反光條\": \"有\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P019','運動水壺 750ml','青嶼 Qingyu','sports-outdoor',420.00,'TWD',0.4400,67,'單手按壓彈蓋，運動中也能快速喝水。Tritan 材質，不含雙酚 A。','{\"容量\": \"750ml\", \"材質\": \"Tritan\", \"重量\": \"160g\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P020','登山健行杖（2 入）','Nordvik','sports-outdoor',1580.00,'TWD',0.3400,71,'鋁合金三節伸縮，快扣式調整長度。附橡膠腳套與泥地雪板。','{\"數量\": \"2 入\", \"材質\": \"7075 鋁合金\", \"重量\": \"單支 240g\", \"長度\": \"65–135 cm\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P021','筋膜按摩球組','Nordvik','sports-outdoor',350.00,'TWD',0.5700,63,'單球與花生球各一，放鬆肩頸、足底與背部。','{\"材質\": \"矽膠\", \"硬度\": \"中硬\", \"內容物\": \"單球 x1、花生球 x1\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P022','玻尿酸保濕精華 30ml','霧島 Kirishima','beauty',1150.00,'TWD',0.6300,84,'三重分子玻尿酸，質地清爽好吸收。適合混合肌與乾性肌。','{\"容量\": \"30ml\", \"主要成分\": \"玻尿酸、維他命 B5\", \"適用膚質\": \"混合肌、乾性肌\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P023','溫和胺基酸洗面乳','霧島 Kirishima','beauty',380.00,'TWD',0.5000,72,'胺基酸潔淨配方，洗後不緊繃。無添加香料。','{\"容量\": \"120g\", \"香料\": \"無\", \"主要成分\": \"胺基酸系界面活性劑\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P024','植萃護手霜三入組','微光 Glimmer','beauty',520.00,'TWD',0.5500,66,'乳油木果油與植物萃取，滋潤不黏膩。三種香味各一入。','{\"容量\": \"30ml x3\", \"香味\": \"白茶、柚子、無花果\", \"主要成分\": \"乳油木果油\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P025','清爽防曬乳 SPF50','霧島 Kirishima','beauty',690.00,'TWD',0.4600,70,'清爽不黏膩的質地，防水防汗，適合日常通勤與戶外活動。','{\"容量\": \"50ml\", \"防水\": \"有\", \"防曬係數\": \"SPF50／PA++++\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P026','淺焙衣索比亞咖啡豆 250g','森焙 Morino Roastery','food-drink',480.00,'TWD',0.3500,78,'衣索比亞耶加雪菲水洗處理，柑橘與花香調性。每週新鮮烘焙。','{\"產區\": \"衣索比亞 耶加雪菲\", \"重量\": \"250g\", \"風味\": \"柑橘、茉莉花、紅茶\", \"烘焙度\": \"淺焙\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P027','高山烏龍茶 150g','雲頂茶作','food-drink',880.00,'TWD',0.4200,74,'海拔 1,200 公尺以上茶區，輕焙火，帶花果香，回甘明顯。','{\"焙火\": \"輕焙火\", \"產地\": \"台灣 嘉義阿里山\", \"重量\": \"150g\"}','2026-10-20','2026-11-15 12:26:29','2026-11-16 04:06:31'),('P028','濾掛咖啡綜合包（20 入）','森焙 Morino Roastery','food-drink',599.00,'TWD',0.3900,76,'四種風味各 5 包，在辦公室也能輕鬆喝到手沖風味。','{\"數量\": \"20 包\", \"風味\": \"衣索比亞、哥倫比亞、巴西、肯亞各 5 包\", \"每包重量\": \"10g\"}','2026-10-20','2026-11-15 12:26:30','2026-11-16 04:06:31'),('P029','綜合堅果隨手包（30 入）','日穀 Rigu','food-drink',750.00,'TWD',0.3300,69,'每日一包，腰果、杏仁、核桃與蔓越莓乾。無調味、無添加糖。','{\"成分\": \"腰果、杏仁、核桃、蔓越莓乾\", \"數量\": \"30 包\", \"每包重量\": \"25g\"}','2026-10-20','2026-11-15 12:26:30','2026-11-16 04:06:31'),('P030','手工牛軋糖禮盒','日穀 Rigu','food-drink',1050.00,'TWD',0.4700,73,'手工製作，奶香濃郁不黏牙。綜合原味、抹茶與蔓越莓三種口味。','{\"口味\": \"原味、抹茶、蔓越莓\", \"重量\": \"450g\", \"保存期限\": \"常溫 60 天\"}','2026-10-20','2026-11-15 12:26:30','2026-11-16 04:06:31');
